package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.XPathException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.QName;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class NullPropertyPointer_createPath_TriageGen1Test {

    @Test
    public void testCreatePath_ThrowsBadFactoryException_WhenParentIsNullPointerAndEqualsNewParent() throws Exception {
        // Setup: parent is a NullPointer and equals the result of parent.createPath(context)
        NodePointer mockParent = mock(NullPointer.class);
        NodePointer mockNewParent = mock(NullPointer.class);
        JXPathContext mockContext = mock(JXPathContext.class);
        JXPathContext.Factory mockFactory = mock(JXPathContext.Factory.class);

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockParent.equals(mockNewParent)).thenReturn(true);
        when(mockContext.getFactory()).thenReturn(mockFactory);

        // NullPropertyPointer is a subclass of NullPointer, so we mock the behavior via a spy or real instance if possible
        // Since we need to trigger createBadFactoryException (protected), we use a spy
        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));

        // Mock the protected method createBadFactoryException to throw an exception as it would in reality
        doThrow(new XPathException("Bad Factory")).when(nullPropertyPointer).createBadFactoryException(mockFactory);

        try {
            nullPropertyPointer.createPath(mockContext, new Object());
        } catch (XPathException e) {
            // Success: exception was thrown
            return;
        }
        throw new AssertionError("Expected XPathException was not thrown");
    }

    @Test
    public void testCreatePath_ReturnsChild_WhenNewParentIsNotPropertyOwnerPointer() throws Exception {
        // Setup
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockResult = mock(NodePointer.class);
        JXPathContext mockContext = mock(JXPathContext.class);
        QName name = new QName("testProperty");
        Object value = new Object();
        int index = 0;

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        // Ensure parent is not NullPointer or doesn't equal newParent to bypass first if
        when(mockParent.equals(mockNewParent)).thenReturn(false);
        // Ensure newParent is not PropertyOwnerPointer
        when(mockNewParent.createChild(eq(mockContext), eq(name), eq(index), eq(value))).thenReturn(mockResult);

        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent);
        // We need to set the name and index via reflection or if the class allows, 
        // but here we assume the internal state is accessible or set via methods.
        // Since we can't easily set 'name' and 'index' directly if they are private, 
        // we rely on the fact that the method uses class fields.
        // For the sake of this test, we assume the implementation of createPath uses instance fields.

        // Because we cannot change the source code, we use a subclass to inject the name/index if they were protected,
        // but since they are likely private, we rely on the fact that we are testing the logic.
        // Note: In a real scenario, you'd use Reflection to set private fields 'name' and 'index'.
        java.lang.reflect.Field nameField = NullPropertyPointer.class.getDeclaredField("name");
        nameField.setAccessible(true);
        nameField.set(nullPropertyPointer, name); // Note: This assumes 'name' is static or instance. 
        // If 'name' is an instance field, use nullPropertyPointer.
        // Looking at the signature, it's an instance field.

        java.lang.reflect.Field indexField = NullPropertyPointer.class.getDeclaredField("index");
        indexField.setAccessible(true);
        indexField.set(nullPropertyPointer, index);

        NodePointer result = nullPropertyPointer.createPath(mockContext, value);

        assert result == mockResult;
        verify(mockNewParent).createChild(mockContext, name, index, value);
    }

    @Test
    public void testCreatePath_RedirectsToPropertyPointer_WhenNewParentIsPropertyOwnerPointer() throws Exception {
        // Setup
        NodePointer mockParent = mock(NodePointer.class);
        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropertyPointer = mock(NodePointer.class);
        NodePointer mockResult = mock(NodePointer.class);
        JXPathContext mockContext = mock(JXPathContext.class);
        QName name = new QName("testProperty");
        Object value = new Object();
        int index = 0;

        when(mockParent.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropertyPointer);
        when(mockPropertyPointer.createChild(eq(mockContext), eq(name), eq(index), eq(value))).thenReturn(mockResult);

        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent);

        java.lang.reflect.Field nameField = NullPropertyPointer.class.getDeclaredField("name");
        nameField.setAccessible(true);
        nameField.set(nullPropertyPointer, name);

        java.lang.reflect.Field indexField = NullPropertyPointer.class.getDeclaredField("index");
        indexField.setAccessible(true);
        indexField.set(nullPropertyPointer, index);

        NodePointer result = nullPropertyPointer.createPath(mockContext, value);

        assert result == mockResult;
        verify(mockPop).getPropertyPointer();
        verify(mockPropertyPointer).createChild(mockContext, name, index, value);
    }
}

// Mocking PropertyOwnerPointer as it is likely a sibling or subclass in the package
interface PropertyOwnerPointer extends NodePointer {
    NodePointer getPropertyPointer();
}
